        self_sha256 = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
        context_instruction = str(context.get("instruction") or "").replace("\r\n", "\n").replace("\r", "\n").rstrip("\n") + "\n"
        context_instruction_sha256 = hashlib.sha256(context_instruction.encode("utf-8")).hexdigest()
        binding_ok = (
            context.get("task_id") == TASK_ID
            and context.get("evaluator_id") == EVALUATOR_ID
            and context_instruction_sha256 == INSTRUCTION_SHA256
            and params.get("expected_instruction_sha256") == INSTRUCTION_SHA256
            and params.get("expected_ruleset_sha256") == RULESET_SHA256
            and params.get("expected_evaluator_source_sha256") == self_sha256
            and params.get("expected_evaluator_id") == EVALUATOR_ID
            and params.get("expected_checkpoint_specs_sha256") == hashlib.sha256(json.dumps(list(CHECKPOINT_SPECS), ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
            and params.get("expected_profile") == "windows1_3"
            and params.get("expected_snapshot") == "sn2"
            and (context.get("windows_vm_profile") in (None, "windows1_3"))
            and (context.get("snapshot_name") in (None, "sn2"))
        )
        if not binding_ok:
            return EvalResult(EvalStatus.ERROR, "task/evaluator digest binding mismatch", {"ruleset_sha256": RULESET_SHA256, "read_only": True})
        try:
            result = controller.run_python_script(_probe(), timeout=int(params.get("timeout", 120)))
            if int(result.get("returncode", result.get("return_code", 0)) or 0): raise RuntimeError(str(result.get("error") or result.get("output") or "probe failed"))
            raw = json.loads(str(result.get("stdout") or result.get("output") or "{}"))
            checkpoint_specs_sha256 = hashlib.sha256(json.dumps(list(CHECKPOINT_SPECS), ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
            raw.update({"task_id": context.get("task_id"), "instruction_sha256": context_instruction_sha256, "ruleset_sha256": params.get("expected_ruleset_sha256"), "evaluator_id": context.get("evaluator_id"), "evaluator_source_sha256": self_sha256, "expected_evaluator_source_sha256": params.get("expected_evaluator_source_sha256"), "checkpoint_specs_sha256": checkpoint_specs_sha256, "profile": context.get("windows_vm_profile") or params.get("expected_profile"), "snapshot": context.get("snapshot_name") or params.get("expected_snapshot")})
            verdict = evaluate_state(raw, mode)
        except Exception as exc:
            return EvalResult(EvalStatus.ERROR, f"OpenPhotoEdit read-only evaluation failed: {type(exc).__name__}: {exc}", {"read_only": True, "business_state_mutations": []})
        verdict.update({"task_id": TASK_ID, "evaluator_id": EVALUATOR_ID, "evaluator_source_sha256": self_sha256, "instruction_sha256": INSTRUCTION_SHA256, "ruleset_spec": RULESET_SPEC, "ruleset_sha256": RULESET_SHA256, "step_groups": STEP_GROUPS, "checkpoint_specs": CHECKPOINT_SPECS, "read_only": True, "business_state_mutations": [], "data_source": "current exact files/build and application-owned unbounded history/final state via non-writable CDP getter"})
        passed = verdict["status"] == "PASS"
        return EvalResult(EvalStatus.PASS if passed else EvalStatus.FAIL, "All strict OpenPhotoEdit2 checks passed" if passed else "OpenPhotoEdit2 strict checks failed: " + ", ".join(verdict["failures"]), verdict)
